class Grid:
    def __init__(self):
        self.grid = [[0]*20 for _ in range(20)]

    def set_pixel(self, r, c, val=2):
        self.grid[r][c] = val

    def get_pixel(self, r, c):
        return self.grid[r][c]

    def draw_line(self, r1, c1, r2, c2):
        """Draw a line using Bresenham's algorithm"""
        dr = 0 if r1 == r2 else 1 if r2 > r1 else -1
        dc = 0 if c1 == c2 else 1 if c2 > c1 else -1
        dy = abs(r2 - r1)
        dx = abs(c2 - c1)

        y = r1 if r1 < r2 else r2  # Step direction
        x = c1 if c1 < c2 else c2

        if dr == 0:
            # Horizontal line
            for c in range(min(c1, c2), max(c1, c2) + 1):
                self.set_pixel(r1, c)
        elif dc == 0:
            # Vertical line  
            for r in range(min(r1, r2), max(r1, r2) + 1):
                self.set_pixel(r, c1)
        else:
            # Diagonal line
            for _ in range(min(dy, dx) + 1):
                if dr > 0:
                    self.set_pixel(y, x)
                    y += 1
                else:
                    self.set_pixel(y, x)
                    y -= 1
                if dc > 0:
                    x += 1
                else:
                    x -= 1

